{
  "status": "graded",
  "criteria": [
    {
      "criterion_id": "c1",
      "level_id": "met",
      "reason": "明确说明 MC 适合有自然终局的 episodic 问题。",
      "evidence_quote": "Monte Carlo is a natural choice for episodic problems with genuine endings.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c2",
      "level_id": "met",
      "reason": "说明 MC 不需要已知模型，只从完整轨迹采样学习。",
      "evidence_quote": "It learns from sampled complete trajectories without a known dynamics model.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c3",
      "level_id": "met",
      "reason": "说明 episode 足够短、可等到终局时 MC 方便。",
      "evidence_quote": "It is convenient when episodes are short enough that waiting for their end is acceptable.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c4",
      "level_id": "met",
      "reason": "说明固定策略、给定状态、独立完整 rollout 下样本回报期望正确，即无偏。",
      "evidence_quote": "With a fixed policy and independent complete rollouts from the specified state, sampled returns have the correct value in expectation.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c5",
      "level_id": "met",
      "reason": "说明 MC 目标不代入下一状态价值的估计，即不自举。",
      "evidence_quote": "The target does not plug in a possibly poor estimate of the next state value.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c6",
      "level_id": "met",
      "reason": "说明 MC 方差可能大，需要平均足够多 episode。",
      "evidence_quote": "Variance can be large so average enough episodes.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c7",
      "level_id": "met",
      "reason": "说明稀疏终局结果可为整条完成轨迹上的访问提供回报。",
      "evidence_quote": "A sparse terminal outcome supplies a return for visits along the completed trajectory.",
      "evidence_source": "text"
    },
    {
      "criterion_id": "c8",
      "level_id": "met",
      "reason": "说明 MC 实现简单，而 TD 更适合在线更新和 continuing 任务。",
      "evidence_quote": "Implementation is simple, while TD is generally more convenient for immediate online updates and continuing tasks.",
      "evidence_source": "text"
    }
  ]
}
